#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <stdlib.h>

#ifdef _OPENMP
# include <omp.h>
#endif

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "mvt.h"

/* -------------------------------------------------------------------------
 * Optional tuning parameters.
 *
 * - MVT_OMP_MIN_N:
 *     Minimum problem size (in N) above which the OpenMP parallel
 *     implementation is enabled. For smaller matrices, the overhead
 *     of thread creation and synchronization can dominate.
 *
 *     You can override this value at compile time, e.g.:
 *       gcc -DMVT_OMP_MIN_N=1024 ...
 * ------------------------------------------------------------------------- */
#ifndef MVT_OMP_MIN_N
# define MVT_OMP_MIN_N 256
#endif


/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    {
      x1[i]  = (DATA_TYPE) (i % n) / n;
      x2[i]  = (DATA_TYPE) ((i + 1) % n) / n;
      y_1[i] = (DATA_TYPE) ((i + 3) % n) / n;
      y_2[i] = (DATA_TYPE) ((i + 4) % n) / n;
      for (j = 0; j < n; j++)
	A[i][j] = (DATA_TYPE) (i*j % n) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x1,N,n),
		 DATA_TYPE POLYBENCH_1D(x2,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x1");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x1[i]);
  }
  POLYBENCH_DUMP_END("x1");

  POLYBENCH_DUMP_BEGIN("x2");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x2[i]);
  }
  POLYBENCH_DUMP_END("x2");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations:
 *  - The two original matrix-vector products
 *
 *       x1[i] += sum_j A[i][j] * y_1[j]
 *       x2[i] += sum_j A[j][i] * y_2[j]
 *
 *    are fused into a single loop nest that processes each A[i][j] once
 *    and reuses it for both x1 and x2. This halves the memory traffic
 *    to A and keeps accesses row-major (contiguous) for better cache
 *    and TLB behavior.
 *
 *  - Local restrict-qualified pointer aliases are used to help the
 *    compiler with alias analysis and enable more aggressive
 *    auto-vectorization.
 *
 *  - A sequential fused implementation is always available. When
 *    compiled with OpenMP (-fopenmp) and for sufficiently large N
 *    (>= MVT_OMP_MIN_N), an optional parallel implementation is used:
 *      * work is distributed across rows of A;
 *      * each thread accumulates its contributions to x2 in a private
 *        buffer to avoid write conflicts;
 *      * a final reduction combines all private x2 buffers into the
 *        global x2. Extra memory is bounded to at most 50% of the
 *        matrix size by limiting the number of threads with respect
 *        to N.
 */
static
void kernel_mvt[[gnu::flatten, gnu::noinline]](int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;
  const int N_ = _PB_N;

  /* Local pointer aliases with restrict qualifiers to improve
     auto-vectorization and reduce redundant alias checks. */
  DATA_TYPE       * __restrict x1_ = x1;
  DATA_TYPE       * __restrict x2_ = x2;
  const DATA_TYPE * __restrict y1_ = y_1;
  const DATA_TYPE * __restrict y2_ = y_2;

#ifdef _OPENMP
  /* -------------------------------------------------------------------
   * Parallel fused implementation (optional, OpenMP enabled build).
   *
   * We parallelize over rows of A. Since every row contributes to all
   * entries of x2, we maintain per-thread partial sums for x2 in a
   * private buffer x2_private[thread][j]. After the parallel region,
   * we reduce these partial sums into the global x2.
   *
   * Memory bound: additional storage is threads * N_ elements.
   * The number of threads is capped so that:
   *
   *     threads * N_ <= 0.5 * N_^2   (i.e., <= 50% of A's size)
   *
   * which in practice also keeps the memory overhead well below 50%
   * of the whole program footprint.
   * ------------------------------------------------------------------- */
  if (N_ >= MVT_OMP_MIN_N)
  {
    int max_threads = omp_get_max_threads();

    /* Respect memory constraint: threads <= N_/2 so that
       threads * N_ <= 0.5 * N_^2. */
    int mem_limited_threads = (N_ > 1) ? (N_ / 2) : 1;
    if (mem_limited_threads < 1)
      mem_limited_threads = 1;

    int threads = max_threads < mem_limited_threads ? max_threads : mem_limited_threads;

    if (threads > 1)
    {
      size_t buf_elems = (size_t)threads * (size_t)N_;
      DATA_TYPE *x2_private = (DATA_TYPE*)calloc(buf_elems, sizeof(DATA_TYPE));
      if (x2_private != NULL)
      {
        /* Parallel region: distribute rows of A across threads. */
#pragma omp parallel num_threads(threads)
        {
          int tid = omp_get_thread_num();
          DATA_TYPE * __restrict x2_loc = x2_private + (size_t)tid * (size_t)N_;

#pragma omp for schedule(static)
          for (i = 0; i < N_; ++i)
          {
            /* Pointer to row i of A for better spatial locality. */
            DATA_TYPE * __restrict Ai = A[i];

            DATA_TYPE xi = x1_[i];          /* accumulate x1[i] in a register */
            const DATA_TYPE y2_i = y2_[i];  /* broadcast value for this row   */

            /* Inner loop over columns: use A[i][j] once to update both
               x1[i] and the thread-local partial x2[j]. */
#pragma omp simd
            for (j = 0; j < N_; ++j)
            {
              const DATA_TYPE aij = Ai[j];
              xi          += aij * y1_[j];
              x2_loc[j]   += aij * y2_i;
            }

            x1_[i] = xi;
          }
        } /* end parallel */

        /* Reduction of thread-local x2 contributions into the global x2. */
        for (j = 0; j < N_; ++j)
        {
          DATA_TYPE sum = (DATA_TYPE)0;
          for (i = 0; i < threads; ++i)
          {
            sum += x2_private[(size_t)i * (size_t)N_ + (size_t)j];
          }
          x2_[j] += sum;
        }

        free(x2_private);
        return; /* Parallel path has completed the computation. */
      }
      /* If allocation fails, fall through to the sequential variant. */
    }
  }
#endif /* _OPENMP */


  /* -------------------------------------------------------------------
   * Sequential fused implementation.
   *
   * We process rows of A one by one. For each A[i][j], we:
   *   - accumulate into x1[i]  :  x1[i] += A[i][j] * y_1[j]
   *   - accumulate into x2[j]  :  x2[j] += A[i][j] * y_2[i]
   *
   * This is algebraically equivalent to the original kernel, but it
   * uses each A[i][j] only once and accesses A row-major, improving
   * data locality and cutting A's memory traffic roughly in half.
   * ------------------------------------------------------------------- */
#pragma scop
  for (i = 0; i < N_; ++i)
  {
    DATA_TYPE * __restrict Ai   = A[i]; /* row pointer */
    DATA_TYPE   xi              = x1_[i];
    const DATA_TYPE y2_i        = y2_[i];

    /* Help GCC's vectorizer: iterations of this loop are independent
       with respect to j (each x2_[j] is updated exactly once per i). */
#if defined(__GNUC__)
#pragma GCC ivdep
#endif
    for (j = 0; j < N_; ++j)
    {
      const DATA_TYPE aij = Ai[j];
      xi        += aij * y1_[j];
      x2_[j]    += aij * y2_i;
    }

    x1_[i] = xi;
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_2, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n,
	      POLYBENCH_ARRAY(x1),
	      POLYBENCH_ARRAY(x2),
	      POLYBENCH_ARRAY(y_1),
	      POLYBENCH_ARRAY(y_2),
	      POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_mvt (n,
	      POLYBENCH_ARRAY(x1),
	      POLYBENCH_ARRAY(x2),
	      POLYBENCH_ARRAY(y_1),
	      POLYBENCH_ARRAY(y_2),
	      POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x1), POLYBENCH_ARRAY(x2)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x1);
  POLYBENCH_FREE_ARRAY(x2);
  POLYBENCH_FREE_ARRAY(y_1);
  POLYBENCH_FREE_ARRAY(y_2);

  return 0;
}
