  /* First MVT:
     x1[i] = x1[i] + sum_j A[i][j] * y_1[j]
     Access pattern: A is traversed by rows (i fixed, j inner),
     which already matches the row-major layout. We just improve
     scalar replacement and add optional parallelism. */
#pragma omp parallel for private(j) schedule(static)
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE acc = x1_[i];              /* scalar accumulator for x1[i] */
      for (j = 0; j < _PB_N; j++)
        acc += A[i][j] * y1_[j];
      x1_[i] = acc;
    }

  /* Second MVT:
     Original:
       for (i)
         for (j)
           x2[i] += A[j][i] * y_2[j];

     We interchange the loops to:
       for (j)
         for (i)
           x2[i] += A[j][i] * y_2[j];

     For each fixed i, the sequence of updates to x2[i] is still
     performed for j = 0.._PB_N-1 in that order; operations on
     different x2[k] are independent. Thus, this preserves the
     exact per-element floating-point accumulation order while
     changing the traversal of A to be row-contiguous (A[j][i]
     with j fixed and i varying), which greatly improves cache
     performance.

     We also hoist y_2[j] into a scalar to avoid redundant loads,
     and add optional OpenMP parallelism over the outer (j) loop. */
#pragma omp parallel for private(i) schedule(static)
  for (j = 0; j < _PB_N; j++)
    {
      const DATA_TYPE y2j = y2_[j];
      /* A[j][i] is contiguous in memory as i varies. */
      for (i = 0; i < _PB_N; i++)
        x2_[i] += A[j][i] * y2j;
    }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x2, DATA_TYPE, N, n);
