/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_mvt[[gnu::flatten, gnu::noinline]](int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  /* Use the PolyBench-provided problem size inside the SCoP. */
  const int nPB = _PB_N;

  /* Local pointer aliases to help the optimizer and to express
   * non-aliasing assumptions (via restrict).  All arrays are
   * allocated disjointly by the PolyBench harness. */
  DATA_TYPE *restrict x1p = &x1[0];
  DATA_TYPE *restrict x2p = &x2[0];
  DATA_TYPE *restrict y1p = &y_1[0];
  DATA_TYPE *restrict y2p = &y_2[0];

  int i, j;

#pragma scop
  /* --------------------------------------------------------------
   * First matrix-vector product:
   *   x1[i] += sum_j A[i][j] * y_1[j]
   *
   * This already has good spatial locality (A traversed by rows,
   * y_1 traversed sequentially).  We:
   *   - hoist x1[i] into a scalar accumulator to reduce memory traffic,
   *   - obtain a row pointer Ai to A[i] for simpler, vectorizable code,
   *   - parallelize over i (independent rows) with OpenMP.
   * -------------------------------------------------------------- */
#pragma omp parallel for private(i,j) schedule(static) default(none) \
    shared(A,x1p,y1p,nPB)
  for (i = 0; i < nPB; i++)
    {
      /* Pointer to row i of A; elements A[i][0..nPB-1] are contiguous. */
      DATA_TYPE *restrict Ai = A[i];
      DATA_TYPE xi = x1p[i];

      for (j = 0; j < nPB; j++)
	xi += Ai[j] * y1p[j];

      x1p[i] = xi;
    }

  /* --------------------------------------------------------------
   * Second matrix-vector product:
   *   x2[i] += sum_j A[j][i] * y_2[j]
   *
   * The naive version accesses A by columns (A[j][i] with j varying
   * fastest), which is very cache-unfriendly for row-major storage.
   *
   * Here we:
   *   - tile the i-dimension (columns) into blocks of size MVT_TILE_I,
   *   - for each tile, iterate over all rows j, using a row pointer Aj,
   *   - within a tile, update a local scratch buffer x2_tile[].
   *
   * This preserves the original accumulation order for each x2[i]
   * (j increases from 0 to nPB-1) while making inner loops walk
   * contiguous segments Aj[ii .. ii+tile-1], greatly improving
   * spatial locality and enabling vectorization.
   *
   * The outer loop over tiles is parallelized; each tile updates a
   * disjoint slice of x2[], so no synchronization is required beyond
   * the implicit barrier at the end of the parallel loop.
   * -------------------------------------------------------------- */
#pragma omp parallel for private(i,j) schedule(static) default(none) \
    shared(A,x2p,y2p,nPB)
  for (int ii = 0; ii < nPB; ii += MVT_TILE_I)
    {
      /* Determine the actual size of this tile (handles edge cases). */
      const int i_end     = (ii + MVT_TILE_I < nPB) ? (ii + MVT_TILE_I) : nPB;
      const int tile_size = i_end - ii;

      /* Scratch buffer for the current tile of x2.  The size is
       * bounded by MVT_TILE_I and therefore small enough to stay in
       * L1/L2 cache.  Each OpenMP thread gets its own instance. */
      DATA_TYPE x2_tile[MVT_TILE_I];

      /* Initialize local tile from global x2. */
      for (i = 0; i < tile_size; i++)
	x2_tile[i] = x2p[ii + i];

      /* Accumulate contributions from each row j into the tile. */
      for (j = 0; j < nPB; j++)
	{
	  const DATA_TYPE y2j = y2p[j];
	  DATA_TYPE *restrict Aj = A[j]; /* row j of A */

	  /* Aj[ii .. i_end-1] is a contiguous slice of row j. */
#pragma omp simd
	  for (i = 0; i < tile_size; i++)
	    x2_tile[i] += Aj[ii + i] * y2j;
	}

      /* Write back the updated tile to global memory. */
      for (i = 0; i < tile_size; i++)
	x2p[ii + i] = x2_tile[i];
    }
#pragma endscop

}


