      DATA_TYPE sum = x1_[i];
      const DATA_TYPE * restrict Ai = &A[i][0];

      /* No loop-carried dependencies in j: safe to vectorise. */
      #pragma omp simd
      for (j = 0; j < Ndim; j++)
        sum += Ai[j] * y1_[j];

      x1_[i] = sum;
